<template>
  <div class="agent-page">
    <header class="agent-header"><div class="agent-title"><span class="agent-symbol" aria-hidden="true">✦</span><div><h1>调度 Agent</h1><p>描述目标，一起构建可执行的工作流。</p></div></div><div class="header-actions"><span v-if="store.config?.configured" class="model-badge"><span />{{ store.config.model }}</span><el-switch :model-value="!!store.config?.enabled" :loading="store.configPending" :disabled="!store.config || (!store.config.enabled && !store.config.configured)" aria-label="启用 AI Agent" @change="toggleAgent" /><button class="action-btn" @click="router.push({ name: 'settings', query: { tab: 'agent' } })">Agent 设置</button><button class="action-btn" @click="historyOpen = true">历史会话</button><button class="action-btn" :disabled="store.sending" @click="startNew">＋ 新会话</button></div></header>
    <div v-if="store.config && (!store.config.enabled || !store.config.configured)" class="config-notice" role="status"><strong>{{ !store.config.configured ? '模型服务尚未配置' : 'Agent 已停用' }}</strong><span>{{ !store.config.configured ? '前往 Agent 设置选择服务商、填写模型与密钥，即可开始对话。已有会话仍可查看。' : '打开上方开关即可继续对话。已有会话和执行回执仍可查看。' }}</span><button class="action-btn" @click="router.push({ name: 'settings', query: { tab: 'agent' } })">前往设置</button><button class="action-btn" :disabled="store.configPending" @click="store.refreshConfig">重新检查</button></div>
    <div v-if="store.error" class="error-banner" role="alert"><span>{{ store.error }}</span><button v-if="store.connection === 'offline'" class="action-btn" @click="store.reconnect">恢复回答</button><button class="dismiss-error" aria-label="关闭提示" @click="store.error = ''">×</button></div>
    <div class="agent-grid" :class="{ 'with-workspace': selectedProposal }">
      <section class="chat-pane" aria-label="Agent 对话">
        <div class="conversation-heading"><span>{{ store.session?.title || '新会话' }}</span><span v-if="store.connection === 'reconnecting'" class="connection-badge">正在恢复连接…</span><button v-if="!selectedProposal && latestProposal" class="action-btn" @click="selectedProposal = latestProposal">打开工作区 ↗</button></div>
        <div ref="chatScroll" class="chat-scroll" @scroll="onScroll">
          <div v-if="store.loading && !store.messages.length" class="loading-state" role="status">正在读取会话…</div>
          <div v-else-if="!store.messages.length" class="chat-empty"><div class="empty-orbit" aria-hidden="true">✦</div><span class="eyebrow">YOUR SCHEDULING COPILOT</span><h2>从一个想法，到自动运行。</h2><p>查询已有工作流、创建定时任务，或在运行前检查代码与依赖。</p><div class="starter-grid"><button v-for="starter in starters" :key="starter.title" :disabled="!ready" @click="draft = starter.prompt; focusComposer()"><span class="starter-icon">{{ starter.icon }}</span><strong>{{ starter.title }}</strong><span>{{ starter.description }}</span><small>开始描述 ↗</small></button></div></div>
          <article v-for="message in store.messages" :key="message.message_id" class="chat-message" :class="message.role"><div class="message-avatar" aria-hidden="true">{{ message.role === 'user' ? '你' : '✦' }}</div><div class="message-content"><div class="message-meta"><strong>{{ message.role === 'user' ? '你' : 'SchedFlow' }}</strong><small v-if="message.status === 'streaming'">正在回答</small></div><template v-for="(block, index) in message.blocks" :key="index">
            <p v-if="block.type === 'assistant_text' && message.role === 'user'" class="user-text">{{ block.text }}</p>
            <div v-else-if="block.type === 'assistant_text'" class="agent-markdown" v-html="safeMarkdown(block.text)" />
            <div v-else-if="block.type === 'workflow_results'" class="workflow-results"><button v-for="job in block.jobs || []" :key="job.job_id" class="workflow-result" @click="setContext(job.job_id, job.name)"><span class="result-icon">◇</span><span><strong>{{ job.name || job.job_id }}</strong><small>{{ job.job_id }} · {{ job.status || '状态待查询' }}</small><small v-if="job.next_run_time">下次运行 {{ date(job.next_run_time) }}</small></span><span class="result-context">添加上下文 ↗</span></button><p v-if="!block.jobs?.length" class="field-hint">没有找到匹配的工作流。</p></div>
            <div v-else-if="block.type === 'clarification'" class="clarification"><p>{{ block.text }}</p><div><button v-for="option in block.options || []" :key="option.value" class="action-btn" :disabled="store.busy || !ready" @click="submitText(option.value)">{{ option.label }}</button></div></div>
            <button v-else-if="block.type === 'proposal'" class="proposal-link" @click="openProposal(block.proposal_id)"><span class="proposal-link-icon">◇</span><span><strong>{{ proposalTitle(block.proposal_id) }}</strong><small>候选 v{{ store.proposals[block.proposal_id]?.version || block.version }} · {{ proposalStatus(block.proposal_id) }}</small></span><span>检查候选 ↗</span></button>
            <OperationCard v-else-if="block.type === 'operation_receipt' || block.type === 'execution'" :operation-id="block.operation_id" />
            <p v-else-if="block.type === 'error'" class="block-error">{{ block.message }}</p>
          </template></div></article>
          <div v-if="store.busy" class="answer-status" aria-live="polite"><span class="thinking-dots"><i /><i /><i /></span>{{ turnLabel }}</div>
        </div>
        <button v-if="!nearBottom && store.messages.length" class="jump-bottom action-btn" @click="scrollBottom">回到最新消息 ↓</button>
        <form class="composer" @submit.prevent="submit"><div v-if="contextJobId" class="context-tag"><span>◇</span><span>{{ contextName || contextJobId }}</span><button type="button" aria-label="移除工作流上下文" @click="clearContext">×</button></div><label class="sr-only" for="agent-prompt">描述你的调度目标</label><textarea id="agent-prompt" ref="composer" v-model="draft" rows="3" maxlength="16000" :disabled="!ready || store.loading" :placeholder="ready ? '描述你的任务、运行时间和预期结果…' : '启用并配置模型后开始对话'" @keydown="onKeyDown" @compositionstart="composing = true" @compositionend="composing = false"/><div class="composer-footer"><span>Enter 发送 · Shift + Enter 换行</span><button v-if="store.busy" type="button" class="action-btn stop-button" @click="store.cancel">■ 停止回答</button><button v-else class="btn-primary send-button" type="submit" :disabled="!draft.trim() || !ready || store.loading">发送 ↑</button></div><p v-if="store.busy" class="stop-hint">停止回答不会取消已提交的工作流执行。</p></form>
      </section>
      <ProposalWorkspace v-if="selectedProposal" :proposal-id="selectedProposal" @close="selectedProposal = ''" />
    </div>
    <el-drawer v-model="historyOpen" title="会话历史" direction="ltr" size="min(380px, 90vw)"><div class="history-actions"><button class="btn-primary" @click="startNew">＋ 新会话</button></div><p v-if="!store.sessions.length" class="field-hint">还没有保存的会话</p><div v-for="item in store.sessions" :key="item.session_id" class="history-item" :class="{ active: item.session_id === store.session?.session_id }"><button class="history-select" @click="selectSession(item.session_id)"><strong>{{ item.title || '新会话' }}</strong><small>{{ item.created_at ? date(item.created_at) : item.session_id }}</small></button><el-popconfirm title="删除此会话及其历史记录？" confirm-button-text="删除" cancel-button-text="保留" @confirm="store.removeSession(item.session_id)"><template #reference><button class="action-btn danger" aria-label="删除会话">×</button></template></el-popconfirm></div></el-drawer>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getJob } from '@/api/jobs'
import { safeMarkdown } from '@/utils/safeMarkdown'
import { shouldSend } from '@/agent/protocol'
import { useAgentStore } from '@/stores/agent'
import ProposalWorkspace from './ProposalWorkspace.vue'
import OperationCard from './OperationCard.vue'
const store = useAgentStore(); const route = useRoute(); const router = useRouter(); const draft = ref(''); const composing = ref(false); const historyOpen = ref(false); const selectedProposal = ref(''); const contextJobId = ref(''); const contextName = ref(''); const chatScroll = ref<HTMLElement | null>(null); const composer = ref<HTMLTextAreaElement | null>(null); const nearBottom = ref(true)
const ready = computed(() => !!store.config?.enabled && !!store.config?.configured && !store.configPending)
async function toggleAgent(value: string | number | boolean) { await store.setEnabled(!!value) }
const latestProposal = computed(() => { const ids = store.messages.flatMap(message => message.blocks.filter(block => block.type === 'proposal').map(block => block.type === 'proposal' ? block.proposal_id : '')); const live = store.activeTurn?.proposals || []; const saved = store.session?.proposals || []; return live[live.length - 1]?.proposal_id || ids[ids.length - 1] || saved[saved.length - 1]?.proposal_id || '' })
const turnLabel = computed(() => store.sending ? '正在发送…' : ({ pending: '正在准备回答…', queued: '正在等待模型…', running: '正在思考与查询…', thinking: '正在思考…', tool_running: '正在查询调度器…', streaming: '正在回答…', cancelling: '正在停止回答…' } as Record<string, string>)[store.activeTurn?.status || ''] || '正在回答…')
const starters = [{ icon: '◷', title: '创建定时任务', description: '把每天重复的事情交给工作流', prompt: '帮我创建一个每天上午 9 点执行的工作流，先问我需要完成的任务。' }, { icon: '◇', title: '查找工作流', description: '了解当前调度和运行状态', prompt: '列出当前的工作流，以及各自的调度时间和启用状态。' }, { icon: '⌘', title: '设计任务依赖', description: '连接 Python、命令与执行结果', prompt: '帮我设计一个多步骤工作流，先下载数据，再处理，最后生成报告。' }]
function date(value: string) { return new Date(value).toLocaleString() }
function proposalTitle(id: string) { const proposal = store.proposals[id]; return proposal?.name || proposal?.after?.name || '工作流候选已准备' }
function proposalStatus(id: string) { return ({ pending: '待确认', awaiting_confirmation: '待确认', committing: '正在提交', approved: '已确认', rejected: '已放弃', expired: '已过期', committed: '已提交', stale: '版本已变化', superseded: '已有新版本' } as Record<string, string>)[store.proposals[id]?.status || ''] || '查看详情' }
function onScroll() { const element = chatScroll.value; if (element) nearBottom.value = element.scrollHeight - element.scrollTop - element.clientHeight < 90 }
async function scrollBottom() { await nextTick(); chatScroll.value?.scrollTo({ top: chatScroll.value.scrollHeight, behavior: 'auto' }); nearBottom.value = true }
function focusComposer() { void nextTick(() => composer.value?.focus()) }
async function submitText(text: string) { if (!ready.value || store.busy || !text.trim()) return false; nearBottom.value = true; const sent = await store.send(text, contextJobId.value || undefined); await scrollBottom(); return sent }
async function submit() { if (!draft.value.trim() || !ready.value || store.busy) return; const text = draft.value; draft.value = ''; const sent = await submitText(text); if (!sent) draft.value = text; focusComposer() }
function onKeyDown(event: KeyboardEvent) { if (!composing.value && shouldSend(event)) { event.preventDefault(); void submit() } }
function openProposal(id: string) { selectedProposal.value = id; if (!store.proposals[id]) void store.loadProposal(id) }
function setContext(jobId: string, name?: string) { contextJobId.value = jobId; contextName.value = name || jobId; focusComposer() }
function clearContext() { contextJobId.value = ''; contextName.value = ''; if (route.query.job_id) void router.replace({ path: '/agent', query: {} }) }
async function startNew() { await store.newSession(); selectedProposal.value = ''; historyOpen.value = false; nearBottom.value = true; focusComposer() }
async function selectSession(id: string) { selectedProposal.value = ''; historyOpen.value = false; await store.openSession(id); nearBottom.value = true; await scrollBottom() }
watch(() => store.messages.map(message => JSON.stringify(message)).join(''), () => { if (nearBottom.value) void scrollBottom() }, { flush: 'post' })
watch(latestProposal, (value, oldValue) => { if (value && value !== oldValue) selectedProposal.value = value })
watch(() => route.query.job_id, async value => { if (typeof value === 'string') { setContext(value); try { const job = await getJob(value); if (contextJobId.value === value) contextName.value = job.name || value } catch { /* Job ID remains useful as explicit context. */ } } }, { immediate: true })
onMounted(async () => { await store.initialize(); if (latestProposal.value) selectedProposal.value = latestProposal.value; await scrollBottom() })
onBeforeUnmount(() => store.disconnect())
</script>
<style scoped>
