.chat-message { display: flex; gap: 12px; max-width: 780px; margin: 0 auto 26px; }.message-avatar { flex-shrink: 0; width: 30px; height: 30px; border: 1px solid var(--border-default); background: var(--bg-base); border-radius: 9px; display: grid; place-items: center; color: var(--color-primary-text); font-size: 19px; }.user .message-avatar { font-size: 11px; color: var(--text-muted); background: var(--bg-surface); }.message-content { flex: 1; min-width: 0; }.message-meta { display: flex; align-items: center; gap: 10px; margin: 4px 0 9px; }.message-meta strong { font-size: 12px; }.message-meta small { font-size: 10px; color: var(--text-muted); }.user-text { white-space: pre-wrap; overflow-wrap: anywhere; color: var(--text-primary); padding: 12px 16px; background: var(--bg-surface); border: 1px solid var(--border-subtle); border-radius: 2px 12px 12px; font-size: 13px; }
.agent-markdown { color: var(--text-secondary); font-size: 13px; line-height: 1.85; overflow-wrap: anywhere; }.agent-markdown :deep(p) { margin-bottom: 10px; }.agent-markdown :deep(h1), .agent-markdown :deep(h2), .agent-markdown :deep(h3) { margin: 18px 0 8px; font-size: 16px; color: var(--text-primary); }.agent-markdown :deep(ul), .agent-markdown :deep(ol) { padding-left: 22px; margin-block: 10px; }.agent-markdown :deep(a) { color: var(--color-primary-text); }.agent-markdown :deep(code) { background: var(--bg-elevated); padding: 2px 5px; border-radius: 4px; font-size: 12px; }.agent-markdown :deep(pre) { overflow: auto; padding: 14px; background: var(--code-bg); color: var(--code-text); margin-block: 10px; border-radius: var(--radius-sm); }.agent-markdown :deep(pre code) { padding: 0; background: none; }.agent-markdown :deep(table) { border-collapse: collapse; display: block; max-width: 100%; overflow: auto; }.agent-markdown :deep(td), .agent-markdown :deep(th) { border: 1px solid var(--border-default); padding: 6px 10px; }.agent-markdown :deep(blockquote) { border-left: 3px solid var(--color-primary); padding-left: 12px; margin-block: 12px; }
.workflow-result, .proposal-link { display: flex; align-items: center; gap: 10px; width: 100%; padding: 14px; margin-block: 8px; border: 1px solid var(--border-default); background: var(--bg-base); border-radius: var(--radius-md); color: var(--text-primary); text-align: left; cursor: pointer; }.workflow-result:hover, .proposal-link:hover { border-color: var(--color-primary); }.workflow-result strong, .proposal-link strong { font-size: 12px; }.workflow-result small, .proposal-link small { display: block; color: var(--text-muted); font-size: 11px; margin-top: 4px; }.result-icon, .proposal-link-icon { color: var(--color-primary-text); font-size: 24px; }.result-context, .proposal-link > span:last-child { color: var(--color-primary-text); font-size: 10px; margin-left: auto; white-space: nowrap; }.clarification { padding: 14px; margin-top: 10px; border: 1px solid var(--border-default); border-radius: var(--radius-md); font-size: 13px; }.clarification > div { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }.block-error { padding: 12px; color: var(--color-danger); background: var(--color-danger-soft); border-radius: var(--radius-sm); white-space: pre-wrap; }
.composer { margin: 0 auto; width: 100%; max-width: 780px; border: 1px solid var(--border-default); background: var(--bg-base); border-radius: 16px; padding: 12px 14px; box-shadow: var(--shadow-sm); }.composer:focus-within { border-color: var(--color-primary); }.composer textarea { border: 0; background: transparent; color: var(--text-primary); resize: none; width: 100%; min-height: 70px; max-height: 160px; outline: none; font: inherit; line-height: 1.8; }.composer textarea::placeholder { color: var(--text-muted); font-size: 13px; }.composer textarea:disabled { cursor: not-allowed; }.composer-footer { display: flex; align-items: center; justify-content: space-between; gap: 10px; }.composer-footer > span { font-size: 10px; color: var(--text-muted); }.send-button { min-height: 34px; padding: 6px 16px; font-size: 12px; }.stop-hint { font-size: 10px; color: var(--text-muted); margin-top: 8px; }.context-tag { display: inline-flex; align-items: center; max-width: 100%; gap: 6px; padding: 4px 8px; margin-bottom: 7px; color: var(--color-primary-text); background: var(--color-primary-soft); border-radius: var(--radius-sm); font-size: 11px; }.context-tag > span:nth-child(2) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.context-tag button { background: none; border: 0; color: inherit; cursor: pointer; font-size: 16px; }.jump-bottom { position: absolute; bottom: 172px; left: 50%; transform: translateX(-50%); box-shadow: var(--shadow-md); z-index: 1; }
