.config-notice, .error-banner { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-radius: var(--radius-md); font-size: 12px; }.config-notice { background: var(--color-warning-soft); color: var(--color-warning); border: 1px solid var(--border-subtle); }.config-notice strong { flex-shrink: 0; }.config-notice span, .error-banner span { flex: 1; }.error-banner { background: var(--color-danger-soft); color: var(--color-danger); }.dismiss-error { border: 0; background: none; color: inherit; font-size: 20px; cursor: pointer; }.loading-state { color: var(--text-muted); text-align: center; margin-top: 40px; }.history-actions { margin-bottom: 20px; }.history-item { display: flex; align-items: center; gap: 10px; border: 1px solid var(--border-subtle); border-radius: var(--radius-md); margin-bottom: 8px; padding: 8px 12px; }.history-item.active { background: var(--color-primary-soft); border-color: var(--color-primary); }.history-select { flex: 1; text-align: left; border: 0; background: none; color: var(--text-primary); padding-block: 6px; cursor: pointer; min-width: 0; }.history-select strong { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 13px; }.history-select small { display: block; margin-top: 4px; color: var(--text-muted); font-size: 11px; }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
